import Cocoa

// Brand identification is a display hint from explicit advertised names, never
// an authentication or compatibility decision. Unknown/custom names stay generic.
enum ShareDeviceBrand: String, CaseIterable {
    case xiaomi, redmi, poco, apple, samsung, huawei, honor, oppo, vivo, iqoo, oneplus, realme, lenovo

    static func identify(_ name: String) -> ShareDeviceBrand? {
        let names: [(ShareDeviceBrand, String)] = [
            (.redmi, #"红米|(^|[^a-z0-9])redmi(?=$|[^a-z])"#),
            (.poco, #"(^|[^a-z0-9])poco(?=$|[^a-z])"#),
            (.xiaomi, #"小米|(^|[^a-z0-9])xiaomi(?=$|[^a-z])"#),
            (.apple, #"苹果|(^|[^a-z0-9])(apple|iphone|ipad|macbook|imac|mac mini|mac studio|mac pro)(?=$|[^a-z])"#),
            (.samsung, #"三星|(^|[^a-z0-9])(samsung|galaxy)(?=$|[^a-z])"#),
            (.huawei, #"华为|(^|[^a-z0-9])huawei(?=$|[^a-z])"#),
            (.honor, #"荣耀|(^|[^a-z0-9])honor(?=$|[^a-z])"#),
            (.oppo, #"(^|[^a-z0-9])oppo(?=$|[^a-z])"#),
            (.vivo, #"(^|[^a-z0-9])vivo(?=$|[^a-z])"#),
            (.iqoo, #"(^|[^a-z0-9])iqoo(?=$|[^a-z])"#),
            (.oneplus, #"一加|(^|[^a-z0-9])oneplus(?=$|[^a-z])"#),
            (.realme, #"真我|(^|[^a-z0-9])realme(?=$|[^a-z])"#),
            (.lenovo, #"联想|(^|[^a-z0-9])(lenovo|thinkpad)(?=$|[^a-z])"#),
        ]
        return names.first { name.range(of: $0.1, options: [.regularExpression, .caseInsensitive]) != nil }?.0
    }
    var title: String {
        switch self {
        case .xiaomi: return "小米"
        case .redmi: return "Redmi"
        case .poco: return "POCO"
        case .apple: return "Apple"
        case .samsung: return "三星"
        case .huawei: return "华为"
        case .honor: return "荣耀"
        case .oppo: return "OPPO"
        case .vivo: return "vivo"
        case .iqoo: return "iQOO"
        case .oneplus: return "一加"
        case .realme: return "realme"
        case .lenovo: return "联想"
        }
    }
    var color: NSColor {
        if [.apple, .honor, .poco, .iqoo, .realme].contains(self) { return .labelColor }
        let rgb: UInt32
        switch self {
        case .xiaomi: rgb = 0xE95700
        case .redmi: rgb = 0xC70025
        case .poco: rgb = 0x242424
        case .apple, .honor, .iqoo: rgb = 0x242424
        case .samsung: rgb = 0x1428A0
        case .huawei: rgb = 0xCF0A2C
        case .oppo: rgb = 0x006F35
        case .vivo: rgb = 0x2354E6
        case .oneplus: rgb = 0xD90016
        case .realme: rgb = 0x665000
        case .lenovo: rgb = 0xD71920
        }
        return NSColor(srgbRed: CGFloat((rgb >> 16) & 255) / 255,
            green: CGFloat((rgb >> 8) & 255) / 255, blue: CGFloat(rgb & 255) / 255, alpha: 1)
    }
    var image: NSImage {
        Self.images[self]!
    }
    private static let images: [ShareDeviceBrand: NSImage] = Dictionary(uniqueKeysWithValues: allCases.map { brand in
        let image: NSImage
        if brand == .apple, let symbol = NSImage(systemSymbolName: "apple.logo", accessibilityDescription: "Apple") {
            image = symbol
        } else if let svg = brandSVGs[brand], let vector = NSImage(data: Data(svg.utf8)) {
            image = vector
        } else {
            // Brands without a bundled vector retain their readable wordmarks.
            let text = brand.title
            image = NSImage(size: NSSize(width: 48, height: 24), flipped: false) { bounds in
                let text = NSAttributedString(string: text, attributes: [.font: NSFont.systemFont(ofSize: 12, weight: .bold), .foregroundColor: NSColor.white])
                let size = text.size()
                text.draw(at: NSPoint(x: (bounds.width - size.width) / 2, y: (bounds.height - size.height) / 2))
                return true
            }
        }
        image.isTemplate = true
        return (brand, image)
    })
}

